Here's a spiral galaxy canvas animation:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Spiral Galaxy</title>
<style>
  html, body { margin: 0; height: 100%; background: #000; overflow: hidden; }
  canvas { display: block; }
</style>
</head>
<body>
<canvas id="sky"></canvas>
<script>
(() => {
  const canvas = document.getElementById('sky');
  const ctx = canvas.getContext('2d');
  let W, H, cx, cy;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
    cx = W / 2;
    cy = H / 2;
  }
  resize();
  window.addEventListener('resize', resize);

  const NUM_STARS = 700;
  const stars = [];

  // Build spiral arm stars
  for (let i = 0; i < NUM_STARS; i++) {
    const arm = i % 2; // two spiral arms
    const t = Math.pow(Math.random(), 0.6);        // bias toward core
    const radius = 20 + t * Math.min(W, H) * 0.45;
    const baseAngle = t * 4.2 + arm * Math.PI;     // spiral winding
    const spread = (Math.random() - 0.5) * 0.55 * (0.4 + t); // arm scatter
    const angle = baseAngle + spread;

    stars.push({
      radius,
      angle,
      baseRadius: radius,
      angularSpeed: (0.05 + 0.35 / (radius + 40)) * (0.8 + Math.random() * 0.4),
      size: Math.random() < 0.85 ? Math.random() * 1.4 + 0.4 : Math.random() * 2.2 + 1.4,
      twinklePhase: Math.random() * Math.PI * 2,
      twinkleSpeed: 0.5 + Math.random() * 2,
      // color variation: blue-white outer, warm yellow core
      hue: 210 - t * 160 + (Math.random() - 0.5) * 40,
      sat: 60 + Math.random() * 40,
      light: 70 + Math.random() * 25
    });
  }

  // Background dust / faint field stars
  const dust = [];
  for (let i = 0; i < 250; i++) {
    dust.push({
      x: Math.random(),
      y: Math.random(),
      size: Math.random() * 1.1 + 0.2,
      alpha: Math.random() * 0.5 + 0.1,
      phase: Math.random() * Math.PI * 2,
      speed: 0.3 + Math.random() * 1.5
    });
  }

  let last = performance.now();

  function draw(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;
    const time = now / 1000;

    // Clear with slight trail for motion smoothing
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(0, 0, W, H);

    // Core glow
    const maxR = Math.min(W, H) * 0.5;
    const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, maxR * 0.55);
    const pulse = 0.85 + Math.sin(time * 0.8) * 0.15;
    glow.addColorStop(0, `rgba(255, 240, 200, ${0.9 * pulse})`);
    glow.addColorStop(0.15, 'rgba(255, 200, 120, 0.5)');
    glow.addColorStop(0.4, 'rgba(180, 140, 255, 0.12)');
    glow.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, W, H);

    // Bright core center
    const core = ctx.createRadialGradient(cx, cy, 0, cx, cy, 26);
    core.addColorStop(0, 'rgba(255, 255, 245, 1)');
    core.addColorStop(0.5, 'rgba(255, 220, 160, 0.85)');
    core.addColorStop(1, 'rgba(255, 200, 120, 0)');
    ctx.fillStyle = core;
    ctx.beginPath();
    ctx.arc(cx, cy, 26, 0, Math.PI * 2);
    ctx.fill();

    // Background dust stars (fixed, twinkling)
    for (const d of dust) {
      const a = d.alpha * (0.6 + 0.4 * Math.sin(time * d.speed + d.phase));
      ctx.fillStyle = `rgba(200, 210, 255, ${a})`;
      ctx.fillRect(d.x * W, d.y * H, d.size, d.size);
    }

    // Spiral stars
    for (const s of stars) {
      // differential rotation: inner stars orbit faster
      s.angle += s.angularSpeed * dt;
      const x = cx + Math.cos(s.angle) * s.radius;
      const y = cy + Math.sin(s.angle) * s.radius * 0.62; // tilted disk

      const tw = 0.65 + 0.35 * Math.sin(time * s.twinkleSpeed + s.twinklePhase);
      const alpha = tw * (0.5 + 0.5 * (1 - s.radius / (Math.min(W, H) * 0.6)));

      ctx.fillStyle = `hsla(${s.hue}, ${s.sat}%, ${s.light}%, ${alpha})`;
      ctx.beginPath();
      ctx.arc(x, y, s.size, 0, Math.PI * 2);
      ctx.fill();
    }

    requestAnimationFrame(draw);
  }

  requestAnimationFrame(draw);
})();
</script>
</body>
</html>
```**Spiral galaxy features:**
- **700 spiral-arm stars** distributed along two logarithmic arms with scatter, biased toward the core
- **Differential rotation** — inner stars orbit faster than outer ones (like a real galaxy), so the spiral slowly winds
- **Color gradient** — warm yellow-white near the core shifting to cool blue-white at the edges, with per-star hue variation
- **Twinkle** — each star pulses with its own phase and speed
- **Glowing core** — a pulsing radial gradient plus a bright center point
- **Tilted disk** — the galaxy is flattened vertically (×0.62) for a 3D-ish perspective feel
- **Background dust** — 250 faint fixed stars twinkling behind the galaxy
- **Motion trails** — semi-transparent clear each frame gives a subtle smearing that softens movement

Everything runs in one self-contained file with no external dependencies. Just save it as an `.html` file and open it in a browser.
